import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';

export default {
  title: 'Components/CallBackLink',
  component: 'call-back-link',
  tags: ['autodocs'],
  argTypes: {
    text: {
      control: 'text',
      description: 'Text displayed for the link',
      defaultValue: 'Get a call back',
    },
  },
};

const Template = ({ text }) => html`
  <call-back-link
    text="${text}"
    @onLinkClick="${action('onLinkClick')}"
  ></call-back-link>
`;

export const Default = Template.bind({});
Default.args = {
  text: 'Get a call back',
};

export const CustomText = Template.bind({});
CustomText.args = {
  text: 'Request a callback',
};
